/**
 * dsh-provider-usage — unit：#503 会话用量趋势（M1 数据层）。
 *
 * 覆盖（方案定稿 v1.2 记账口径 + 两级聚合 + 分片存储 + tracker 组合）：
 * - collector：usage 定稿主信号 / text-delta 热路径不计 / 重复 usage 校正不重记 /
 *   retry 逐次计（新 header 边界）/ message 补记与校正 / interrupted /
 *   归属缺失入未识别桶 / message.source 副源 / turn-end 定稿记忆保留（防乱序双算）/
 *   turn 计数 / tool 计数 / 分级 TTL / 会话销毁清理 /
 *   非结算事件 default 忽略（developer/message·end-seed 等）/
 *   fork 仅计 live 新增（seed 边界不产出·子会话独立起算·无 seq 过滤分支）/
 *   用量二选一回归（顶层 ?? stream 末条·末条胜出·非裸形态不认）
 * - 评审修复：P2-1 counter 记账 time 取 event.time / P2-2 message 补记定稿后
 *   headerSeen 对称重置（迟到 usage 不双算）/ P2-3 done 记忆 Map 化（retry 记忆 +
 *   TREND_DONE_MAX 淘汰）/ P2-6 归属不一致 onAnomaly 告警（不覆盖主源）
 * - aggregator：null 语义求和 / 日切压实（cells 不动）/ rebuild / mergeAggRows /
 *   日/周/月序列（周一锚点、月区间、空日 null、provider 过滤）/ 时钟回拨旧日落桶
 * - store：明细 roundtrip / 坏行跳过 / 聚合原子写 / prune /
 *   P1-3 appendRows 成功日集合（部分失败不重复 append）/ P2-4 坏行校验拒绝 /
 *   P2-7 writeAggDay 清理同日残留 tmp
 * - 交叉：P0-1 HistoryStore.pruneAll 不误删 trend 分片
 * - tracker：启动重建（聚合权威）/ 过去日明细自愈 / 当日明细防二次落盘 /
 *   防抖刷盘 / dispose await 刷盘 / 日切压实与重启不双算 / 迟到旧日行合并防覆盖
 * - 复核 M1（#633）：混存分片重启重建 dirDays 恢复（dir 行真读回）/ 自愈压实
 *   dir 行 pending 同源折算不丢 / pruneDays 联动删除 dirDays
 * - 复核 P1-1（#633）：dirDays 单源化——过去日不随 dropPending 删除（跨天柱
 *   不失）/ rebuild 明细计数行平行折算（同日重启续 apply 双算防线）/ correct
 *   校正双面同步（dirDays 与 cells 不漂移）
 * - config：trendRetentionDays 归一化
 *
 * #722 阶段 1 迁移：脚本式顶层断言 → describe/it（每条断言一个 it）。原块内
 * 「动作 → 断言 → 新动作 → 新断言」的交错顺序在 beforeAll 内逐行保留，并在每个原
 * 断言位置取 structuredClone 快照，it 只读快照——避免把动作前置导致后续断言看到
 * 错误状态（快照必须复制：存引用会被后续动作改写）。
 */
import {
  mkdtempSync,
  existsSync,
  readFileSync,
  writeFileSync,
  mkdirSync,
  utimesSync,
  rmdirSync,
  rmSync,
} from "node:fs";
import { join } from "node:path";
import { tmpdir } from "node:os";
import { afterAll, beforeAll, describe, expect, it } from "vitest";
// 白盒直连深路径（#768 B波）：日界纯面经 shared 门面，不走组合根转发。
import { dayKey } from "../../../src/shared/interface.ts";
// 白盒直连深路径（#768 B波）：历史存储经历史域门面，不走组合根转发。
import { HistoryStore } from "../../../src/server/history/interface.ts";
import { TrendTracker } from "../../../src/server/aggregate/interface.ts";
import { TREND_ROW_VERSION, TREND_UNIDENTIFIED } from "../../../src/server/shared/interface.ts";
import { normalizeConfig, DEFAULT_CONFIG } from "../../../src/shared/interface.ts";
// 白盒直连深路径（#768 B波）：趋势聚合/采集纯面经域门面，不走组合根转发。
import {
  TrendAggregator,
  TrendStore,
  mergeAggRows,
  mergeDirRows,
  mergeHourRows,
  type TrendStackPart,
  type TrendStackPoint,
  type TrendWindowSummary,
} from "../../../src/server/aggregate/interface.ts";
import type { PendingEntry } from "../../../src/server/aggregate/aggregator.ts";
import {
  TrendCollector,
  TREND_DONE_MAX,
  type TrendAggRow,
  type TrendCallRecord,
  type TrendCell,
  type TrendCounterRecord,
  type TrendEmit,
  type TrendHourRow,
} from "../../../src/server/collect/interface.ts";
import type { SessionEvent } from "@deepseek-ai/dsh-session/types";
import {
  isValidShardRow,
  sanitizeDirName,
  sumToken,
  metricValue,
  type TrendCounterRow,
  type TrendDetailRow,
  type TrendDirRow,
} from "../../../src/server/shared/interface.ts";

// ---------------------------------------------------------------- 工具

/** 固定本地时刻：2026-09-04（周五）12:00。 */
const T0 = new Date(2026, 8, 4, 12, 0, 0).getTime();
const DAY0 = dayKey(T0); // 2026-09-04
const HOUR = 3600_000;

/**
 * 事件工厂。0.1.5 迁移适配：旧用例以 `assistant/chunk` + 内嵌 usage 表达「一次
 * usage 到达」，而官方已移除该事件、usage 改由结算事件承载——这里把 usage chunk
 * 形态映射为 assistant/message 结算形态（token 与时间语义不变），使下方用例的
 * 断言继续在**原口径**上成立。非 usage 的 chunk（text-delta 等）在新形态下不构成
 * 调用证据，映射为空 stream 的 assistant/attempt（collector 对无 usage attempt 不入账）。
 */
// 事件信封经 unknown 断言为 SessionEvent：与生产边界同构（最小 payload + 品牌类型，
// collector 防御性解析——ledger 同款）。
function ev(type: string, data: Record<string, unknown>, time: number, seq = 1): SessionEvent {
  if (type === "assistant/chunk") {
    const payload = data as {
      turn?: unknown;
      step?: unknown;
      chunk?: { type?: unknown; usage?: unknown };
    };
    if (payload.chunk?.type !== "usage") {
      return {
        type: "assistant/attempt",
        seq,
        time,
        data: { turn: payload.turn, step: payload.step, stream: [] },
      } as unknown as SessionEvent;
    }
    return {
      type: "assistant/message",
      seq,
      time,
      data: {
        turn: payload.turn,
        step: payload.step,
        usage: payload.chunk.usage,
        stream: [{ type: "chunk", time, chunk: payload.chunk }],
      },
    } as unknown as SessionEvent;
  }
  return { type, seq, time, data } as unknown as SessionEvent;
}
const HEADER = (provider = "deepseek", model = "deepseek-chat") => ({
  header: { config: { provider, model } },
  reason: "initial",
});
const USAGE = (input = 100, output = 50, cacheRead = 0, cacheWrite = 0) => ({
  turn: 1,
  step: 1,
  chunk: {
    type: "usage",
    usage: {
      inputTokens: input,
      outputTokens: output,
      cacheReadTokens: cacheRead,
      cacheWriteTokens: cacheWrite,
    },
  },
});
const MESSAGE = (usage: Record<string, unknown> | null, opts: { interrupted?: boolean } = {}) => ({
  turn: 1,
  step: 1,
  message: {
    role: "assistant",
    source: { kind: "model", provider: "deepseek", model: "deepseek-chat" },
  },
  ...(usage !== null ? { usage } : {}),
  ...(opts.interrupted ? { interrupted: true } : {}),
});

function makeCollector(now: () => number = () => T0) {
  const emitted: TrendEmit[] = [];
  const collector = new TrendCollector({ now, emit: (e) => emitted.push(e) });
  // collector 直接吃字符串 session id（id 提取在 tracker 层）；对象/null 经此解包以覆盖非法输入防御
  // null 事件为非法输入防御用例（collector 就地吞掉）：边界断言与 ev 工厂同理。
  const send = (session: string | { id: string }, event: SessionEvent | null) =>
    collector.handleEvent(
      typeof session === "string" ? session : session?.id,
      event as SessionEvent,
    );
  return { collector, emitted, send };
}

const callsOf = (emitted: TrendEmit[]): TrendCallRecord[] =>
  emitted
    .filter((e): e is Extract<TrendEmit, { type: "call" }> => e.type === "call")
    .map((e) => e.record);
const correctsOf = (emitted: TrendEmit[]) =>
  emitted
    .filter((e): e is Extract<TrendEmit, { type: "correct" }> => e.type === "correct")
    .map((e) => e.record);
const countersOf = (emitted: TrendEmit[]): TrendCounterRecord[] =>
  emitted
    .filter((e): e is Extract<TrendEmit, { type: "counter" }> => e.type === "counter")
    .map((e) => e.record);

/**
 * 观测快照：在原断言点结构化复制观测值。原脚本式用例「动作 → 断言 → 新动作 →
 * 新断言」交错执行，断言读到的必须是该时点的值；迁为 it 后动作全部先在 beforeAll
 * 重放，若不复制则后续动作会改写断言读到的引用（兄弟文件曾出现条数漂移）。
 */
const snapshot = <T>(value: T): T => structuredClone(value);

/** 旧格式 call 定稿（无 dir 键）：聚合器遇缺键跳过目录累加（与显式未识别桶不等价——
 * 补 dir 会改变 dirDays，故保持缺键原样，仅做类型面收敛）。 */
const callOf = (record: Omit<TrendCallRecord, "dir"> & { dir?: string }): TrendEmit => ({
  type: "call",
  record: record as TrendCallRecord,
});
/** 旧格式 counter 定稿（无 dir 键 + 宽松计数；同上缺键语义）。 */
const counterOf = (
  record: Omit<TrendCounterRecord, "dir" | "turns" | "toolCalls"> & {
    dir?: string;
    turns?: number;
    toolCalls?: number;
  },
): TrendEmit => ({ type: "counter", record: record as TrendCounterRecord });

// ---------------------------------------------------------------- collector：定稿主信号
// 不变量1：身份快照（event 归属折叠正确）——request/header 折叠为 per-session 归属主源，
// usage chunk 定稿按当前折叠归属出账（R8 四不变量归组；台账守恒见 layer-architecture.md §2 E2）。

describe("collector：定稿主信号——usage 到达即定稿", () => {
  let calls: TrendCallRecord[];
  let correctCount: number;

  beforeAll(() => {
    const { emitted, send } = makeCollector();
    const s = { id: "s1" };
    send(s, ev("request/header", HEADER(), T0, 1));
    send(
      s,
      ev(
        "assistant/chunk",
        { turn: 1, step: 1, chunk: { type: "text-delta", index: 0, text: "hi" } },
        T0,
        2,
      ),
    );
    send(s, ev("assistant/chunk", USAGE(100, 50, 10, 5), T0 + 1000, 3));
    calls = snapshot(callsOf(emitted));
    correctCount = emitted.filter((e) => e.type === "correct").length;
  });

  it("usage chunk 到达即定稿：一次调用", () => {
    expect(calls.length).toBe(1);
  });

  it("归属主源 = request/header 折叠", () => {
    expect(calls[0].provider).toBe("deepseek");
  });

  it("归属 model", () => {
    expect(calls[0].model).toBe("deepseek-chat");
