    expect(calls[0].retry).toBe(1);
  });

  it("定稿时间 = 事件 time", () => {
    expect(calls[0].time).toBe(T0 + 1000);
  });

  it("text-delta 与首定稿不产生校正", () => {
    expect(correctCount).toBe(0);
  });
