describe("aggregator：堆叠柱序列 seriesStacked / 窗口摘要 windowSummary（#503 M2）", () => {
  let dayKeys: string[];
  let daySeries0: TrendStackPoint;
  let daySeries1Parts: TrendStackPart[];
