        provider: "p",
        model: "m",
        input: 10,
        output: 5,
        cacheRead: null,
        cacheWrite: null,
        calls: 2,
        turns: 1,
        toolCalls: 0,
      }),
    );
    writeFileSync(
      join(detDir, `${day1}.jsonl`),
      `${JSON.stringify({ v: 1, kind: "detail", time: T0, day: day1, session: "sx", turn: 1, step: 1, retry: 1, provider: "p", model: "m", input: 999, output: 999, cacheRead: null, cacheWrite: null, calls: 1 })}\n`,
    );
