describe("#532 派生维度：空窗口 / 除零 / 跨月连续 / 名称防御", () => {
  let empty: StatsSnapshot;
  let zeroPrev: StatsSnapshot;
  let crossMonth: StatsSnapshot;
  let hostile: StatsSnapshot;

  beforeAll(() => {
    const cell = (calls: number, input: number | null): TrendCell => ({
