/**
 * dsh-provider-usage — unit：R8 台账守恒（不变量4）事件回放式端到端对账（#670）。
 *
 * 为什么要端到端回放（真缺口定位，layer-architecture.md §2 E2）：不变量 1/2/3（身份快照 /
 * 防双计 / 残差归未识别）已被 unit-trend.test.ts 分段覆盖；唯「台账守恒」从未被断言——
 * Σ事件 == buckets == agg == dirRows + unidentified 是 D2 aggregator 拆分的前置安全网
 * （拆分后若压实/折算逻辑漂移，本文件应第一时间红）。
 *
 * 对账口径（四视角，与 aggregator 记账语义一一对应）：
 * - a. Σ事件：emitted 中 call 事件数（correct 只覆盖 token 不新增调用计数）；token 按
 *   最终值求和——同一 fold 键 (session,turn,step,retry) 的 call 先入账、后续 correct
 *   覆盖为该键的最终 tokens（与 applyCorrect 的「回退旧值再累加新值」语义等价，
 *   因为正确路径下 correct 必命中 pending 内该键的最后一条 detail）。
 * - b. buckets：aggregator 内存聚合面（days 桶 cells 合计，buckets() 公开查询面）。
 * - c. agg：rollupSnapshot(day).aggRows 合计——压实折算只做「落盘形态转换」，
 *   与 cells 同源（apply 已累加，折算不二次累加）。
 * - d. dirRows + unidentified：rollupSnapshot(day).dirRows 合计（pending 中带 dir 键的
 *   事实折算）与 dirRows() 快照（dirDays 桶 + 每日残差投影）双线对齐；unidentified
 *   份额逐键对齐（归属/目录缺失的事实不静默丢弃、不双计）。无 dir 键的行只进 agg 不进
 *   dir（旧格式 rebuild 行），目录守恒以「有 dir 事实」为界——本回放全部经 collector
 *   apply 路径，collector.dirOf 恒返回 string（缺失时 TREND_UNIDENTIFIED），
 *   故目录守恒基准 == 聚合面基准。
 * - null 语义：缺失维度（null）不参与求和（sumToken）；0 是有效数字参与求和。
 *   校正若把数字改为 null，cell 增量修正 sub(v,null)=-v 会把值折回（0 残留为 0 属
 *   既有 null-aware 增量语义），故本回放中 correct 一律带完整四维 token，避免该
 *   既有边界干扰守恒判定（该边界不在本文件范围，unit-trend 校正段已覆盖其行为）。
 *
 * 场景清单（单次回放全覆盖）：request/header 归属折叠、assistant/chunk usage 定稿、
 * 同调用重复 usage（产生 correct 校正）、message 补记（含零 usage 与 interrupted）、
 * retry 逐次计（同 fold 键新 header 后 retry+1）、turn/end 与 tool/call（counter 事件）、
 * 归属缺失（provider/model 缺失 → TREND_UNIDENTIFIED）、#633 目录归属两条线
 * （合法 dir 经 resolveCwd 净化、缺失归 TREND_UNIDENTIFIED）、跨天（DAY0/DAY1 逐日对账）。
 */
import { afterAll, describe, expect, it } from "vitest";
// 白盒直连深路径（#768 B波）：日界纯面经 shared 门面，不走组合根转发。
import { dayKey } from "../../../src/shared/interface.ts";
// 白盒直连深路径（#768 B波续批）：趋势双文件簇经域门面，不走组合根转发。
import { TrendAggregator } from "../../../src/server/aggregate/interface.ts";
import {
  TrendCollector,
  type TrendCollectorOptions,
  type TrendEmit,
  type TrendTokens,
} from "../../../src/server/collect/interface.ts";
import { sumToken, TREND_UNIDENTIFIED } from "../../../src/server/shared/interface.ts";
import type { SessionEvent } from "@deepseek-ai/dsh-session/types";

// ---------------------------------------------------------------- 工具（与 unit-trend.test.ts 同口径）

/** 固定本地时刻：2026-09-04（周五）12:00 与次日（跨天对账）。 */
const T0 = new Date(2026, 8, 4, 12, 0, 0).getTime();
const T1 = T0 + 86400000; // 2026-09-05（DAY1）
const DAY0 = dayKey(T0);
const DAY1 = dayKey(T1);

/**
 * 事件工厂。0.1.5 迁移适配（与 unit-trend.test.ts 同口径）：旧用例以
 * `assistant/chunk` + 内嵌 usage 表达一次 usage 到达，官方已移除该事件、usage 改由
 * 结算事件承载——这里把 usage chunk 形态映射为 assistant/message 结算形态；
 * 非 usage chunk 映射为空 stream 的 assistant/attempt（不构成调用证据）。
 */
// 事件信封经 unknown 断言为 SessionEvent：与生产边界同构（apply 经 ctx.on 收到的事件在类型面即
// SessionEvent，运行时局部可缺 payload，collector 防御性解析——测试侧同契约）。
function ev(type: string, data: Record<string, unknown>, time: number, seq = 1): SessionEvent {
  if (type === "assistant/chunk") {
    const payload = data as {
      turn?: unknown;
      step?: unknown;
      chunk?: { type?: unknown; usage?: unknown };
    };
    if (payload.chunk?.type !== "usage") {
      return {
        type: "assistant/attempt",
        seq,
        time,
        data: { turn: payload.turn, step: payload.step, stream: [] },
      } as unknown as SessionEvent;
    }
    return {
      type: "assistant/message",
      seq,
      time,
      data: {
        turn: payload.turn,
        step: payload.step,
        usage: payload.chunk.usage,
        stream: [{ type: "chunk", time, chunk: payload.chunk }],
      },
    } as unknown as SessionEvent;
  }
  return { type, seq, time, data } as unknown as SessionEvent;
}
const HEADER = (provider: string, model: string) => ({
  header: { config: { provider, model } },
  reason: "initial",
});
/** usage chunk：cacheRead/cacheWrite 省略时为 undefined → parseTokens 记 null（缺失维度语义）。 */
const USAGE = (
  turn: number,
  step: number,
  input: number,
  output: number,
  cacheRead?: number,
  cacheWrite?: number,
) => ({
  turn,
  step,
  chunk: {
    type: "usage",
    usage: {
      inputTokens: input,
      outputTokens: output,
      cacheReadTokens: cacheRead,
      cacheWriteTokens: cacheWrite,
    },
  },
});
/** assistant/message：source 缺省 = 无副源（归属缺失路径）；usage 为 null = 零 usage 补记。 */
const MESSAGE = (
  turn: number,
  step: number,
  usage: Record<string, unknown> | null,
  opts: { source?: { kind: string; provider: string; model: string }; interrupted?: boolean } = {},
) => ({
  turn,
  step,
  message: { role: "assistant", ...(opts.source === undefined ? {} : { source: opts.source }) },
  ...(usage === null ? {} : { usage }),
  ...(opts.interrupted ? { interrupted: true } : {}),
});

function makeCollector(resolveCwd: TrendCollectorOptions["resolveCwd"]) {
  const emitted: TrendEmit[] = [];
  const collector = new TrendCollector({ now: () => T0, resolveCwd, emit: (e) => emitted.push(e) });
  const send = (session: string | { id: string }, event: SessionEvent) =>
    collector.handleEvent(typeof session === "string" ? session : session?.id, event);
  return { collector, emitted, send };
}

/** #633 目录归属：s1/s3 合法 cwd（净化 basename），s2/s4 缺失（归未识别桶）。 */
const resolveCwd = (session: string): string | undefined =>
  (({ s1: "/home/u/proj-a", s3: "/home/u/proj-b" }) as Record<string, string>)[session];

// ---------------------------------------------------------------- 回放序列

const { emitted, send } = makeCollector(resolveCwd);

// DAY0 —— s1：合法归属 + 合法目录 + correct 校正 + retry 逐次计 + turn/tool 计数
send("s1", ev("request/header", HEADER("deepseek", "deepseek-chat"), T0, 1)); // 归属主源折叠
send("s1", ev("assistant/chunk", USAGE(1, 1, 100, 50, 10, 5), T0 + 1000, 2)); // 定稿 call#1（retry1）
send("s1", ev("assistant/chunk", USAGE(1, 1, 120, 60, 0, 0), T0 + 2000, 3)); // 同调用重复 usage → correct
send(
  "s1",
  ev(
    "assistant/message",
    MESSAGE(1, 1, { inputTokens: 200, outputTokens: 80, cacheReadTokens: 2, cacheWriteTokens: 1 }),
    T0 + 3000,
    4,
  ),
); // 已定稿 message → correct（覆盖）
send("s1", ev("request/header", HEADER("deepseek", "deepseek-chat"), T0 + 5000, 5)); // 重试边界
send("s1", ev("assistant/chunk", USAGE(1, 1, 70, 30), T0 + 6000, 6)); // retry2 逐次入账
send(
  "s1",
  ev("tool/call", { turn: 1, step: 1, callId: "c1", name: "bash", arguments: "{}" }, T0 + 7000, 7),
); // counter toolCalls
send(
  "s1",
  ev("tool/call", { turn: 1, step: 1, callId: "c2", name: "bash", arguments: "{}" }, T0 + 8000, 8),
); // counter toolCalls
send("s1", ev("turn/end", { turn: 1, reason: { kind: "completed" } }, T0 + 9000, 9)); // counter turns

// DAY0 —— s2：归属缺失（无 header 无 source）+ interrupted 补记 + 后续 usage（未识别桶）
send(
  "s2",
  ev(
    "assistant/message",
    MESSAGE(1, 1, { inputTokens: 30, outputTokens: 20 }, { interrupted: true }),
    T0 + 10000,
    10,
  ),
); // 补记 call（interrupted）
send("s2", ev("assistant/chunk", USAGE(2, 1, 10, 5), T0 + 11000, 11)); // 未识别 call
send(
  "s2",
  ev(
    "tool/call",
    { turn: 1, step: 1, callId: "c1", name: "bash", arguments: "{}" },
    T0 + 12000,
    12,
  ),
); // counter toolCalls（未识别）
send("s2", ev("turn/end", { turn: 1, reason: { kind: "completed" } }, T0 + 13000, 13)); // counter turns（未识别）

// DAY1 —— s3：合法 dir（proj-b）+ 零 usage 补记；s4：目录缺失归未识别 + 合法归属
send("s3", ev("request/header", HEADER("deepseek", "deepseek-reasoner"), T1, 14));
send("s3", ev("assistant/chunk", USAGE(1, 1, 50, 25, 0, 50), T1 + 1000, 15)); // call（dir=proj-b）
send("s3", ev("assistant/message", MESSAGE(2, 1, null), T1 + 2000, 16)); // 零 usage 补记：调用照计、token null
send("s3", ev("turn/end", { turn: 1, reason: { kind: "completed" } }, T1 + 3000, 17)); // counter turns（dir=proj-b）
send("s4", ev("request/header", HEADER("opencode", "glm-4"), T1 + 3100, 18));
send("s4", ev("assistant/chunk", USAGE(1, 1, 8, 4, 1, 0), T1 + 4000, 19)); // call（dir=unidentified）

// emitted 结构 sanity（0.1.5：一次结算一条 call；counter 独立；无校正事件）
const calls = emitted
  .filter((e): e is Extract<TrendEmit, { type: "call" }> => e.type === "call")
  .map((e) => e.record);
const corrects = emitted
  .filter((e): e is Extract<TrendEmit, { type: "correct" }> => e.type === "correct")
  .map((e) => e.record);
const counters = emitted
  .filter((e): e is Extract<TrendEmit, { type: "counter" }> => e.type === "counter")
  .map((e) => e.record);

// ---------------------------------------------------------------- 对账

const agg = new TrendAggregator();
for (const e of emitted) agg.apply(e);

// ---- 期望值：Σ事件（a 视角）——fold 键最终 tokens（correct 覆盖语义）+ counter 计数 ----
/** 台账合计行（token 四维 null-aware + 计数三维；TrendCell/Agg/Dir 行结构子集）。 */
interface TotalsRow {
  input: number | null;
  output: number | null;
  cacheRead: number | null;
  cacheWrite: number | null;
  calls: number;
  turns: number;
  toolCalls: number;
}
const ZERO = (): TotalsRow => ({
  input: null,
  output: null,
  cacheRead: null,
  cacheWrite: null,
  calls: 0,
  turns: 0,
  toolCalls: 0,
});
const TOKEN_FIELDS = ["input", "output", "cacheRead", "cacheWrite"] as const;
const NUM_FIELDS = ["calls", "turns", "toolCalls"] as const;
const ALL_FIELDS = [...TOKEN_FIELDS, ...NUM_FIELDS];

function addTokens(acc: TotalsRow, tokens: TrendTokens | null) {
  if (tokens === null) return acc;
  for (const f of TOKEN_FIELDS) acc[f] = sumToken(acc[f], tokens[f]);
  return acc;
}
/** 十数值字段同构行（cell / agg / dir 行）并入合计。 */
function addRowTotals(acc: TotalsRow, row: TotalsRow) {
  for (const f of TOKEN_FIELDS) acc[f] = sumToken(acc[f], row[f]);
  for (const f of NUM_FIELDS) acc[f] += row[f];
  return acc;
}

// 身份快照基准：fold 键 → { day, dir, tokens }（correct 覆盖 tokens；day/dir 取 call 定稿事实）
const finalByKey = new Map<string, { day: string; dir: string; tokens: TrendTokens | null }>();
for (const e of emitted) {
  if (e.type === "call") {
    const r = e.record;
    finalByKey.set(`${r.session}\u0000${r.turn}\u0000${r.step}\u0000${r.retry}`, {
      day: dayKey(r.time),
      dir: r.dir,
      tokens: r.tokens,
    });
  } else if (e.type === "correct") {
    const r = e.record;
    const cur = finalByKey.get(`${r.session}\u0000${r.turn}\u0000${r.step}\u0000${r.retry}`);
    if (cur !== undefined) cur.tokens = r.tokens; // 校正覆盖（与 applyCorrect 命中语义一致）
  }
}

const expectByDay = new Map<string, TotalsRow>(); // day → 全量合计
const expectByDayDir = new Map<string, Map<string, TotalsRow>>(); // day → Map<dir, 合计>
const dayTotals = (day: string): TotalsRow => {
  let t = expectByDay.get(day);
  if (t === undefined) {
    t = ZERO();
    expectByDay.set(day, t);
  }
  return t;
};
const dayDirTotals = (day: string, dir: string): TotalsRow => {
  let byDir = expectByDayDir.get(day);
  if (byDir === undefined) {
    byDir = new Map();
    expectByDayDir.set(day, byDir);
  }
  let t = byDir.get(dir);
  if (t === undefined) {
    t = ZERO();
    byDir.set(dir, t);
  }
  return t;
};
for (const { day, dir, tokens } of finalByKey.values()) {
  const e = dayTotals(day);
  e.calls += 1;
  addTokens(e, tokens);
  const d = dayDirTotals(day, dir);
  d.calls += 1;
  addTokens(d, tokens);
}
for (const c of counters) {
  const day = dayKey(c.time);
  const e = dayTotals(day);
  e.turns += c.turns;
  e.toolCalls += c.toolCalls;
  const d = dayDirTotals(day, c.dir);
  d.turns += c.turns;
  d.toolCalls += c.toolCalls;
}

// ---- 对账断言（失败消息给出视角 / 日 / 键 / 期望与实得，精确缺账多账定位）----
function assertEqualTotals(label: string, expected: TotalsRow, actual: TotalsRow) {
  for (const f of ALL_FIELDS) {
    expect(
      actual[f],
      `${label}：字段 ${f} 不守恒——期望 ${expected[f]}，实得 ${actual[f]}（${expected[f] === null || actual[f] === null ? "null 语义参与" : `差 ${actual[f] - expected[f]}`}）`,
    ).toBe(expected[f]);
  }
}

function bucketsTotalsOf(day: string): TotalsRow {
  const acc = ZERO();
  const b = agg.buckets().find((d) => d.day === day);
  if (b !== undefined) for (const p of b.providers) addRowTotals(acc, p.cell);
  return acc;
}
function aggRowsTotalsOf(day: string): TotalsRow {
  const acc = ZERO();
  for (const r of agg.rollupSnapshot(day).aggRows) addRowTotals(acc, r);
  return acc;
}
function dirRowsTotalsOf(day: string): TotalsRow {
  const acc = ZERO();
  for (const r of agg.rollupSnapshot(day).dirRows) addRowTotals(acc, r);
  return acc;
}
function dirSnapshotTotalsOf(day: string): TotalsRow {
  const acc = ZERO();
  for (const r of agg.dirRows()) if (r.day === day) addRowTotals(acc, r);
  return acc;
}
function dirRowsOfDirTotals(day: string, dir: string): TotalsRow {
  const acc = ZERO();
  for (const r of agg.rollupSnapshot(day).dirRows) if (r.dir === dir) addRowTotals(acc, r);
  return acc;
}
function dirSnapshotOfDirTotals(day: string, dir: string): TotalsRow {
  const acc = ZERO();
  for (const r of agg.dirRows()) if (r.day === day && r.dir === dir) addRowTotals(acc, r);
  return acc;
}

const days = [...expectByDay.keys()].sort();

describe("emitted 结构 sanity（0.1.5：一次结算一条 call；counter 独立；无校正事件）", () => {
  it("Σ事件：call 事件数 = 9（每次结算一条）", () => {
    expect(calls.length).toBe(9);
  });

  it("0.1.5 结算自带完整 token，无校正事件", () => {
    expect(corrects.length).toBe(0);
  });

  it("turn/end×3 + tool/call×3 = 6 个 counter 事件", () => {
    expect(counters.length).toBe(6);
  });

  it("归属折叠正确（s1 header 主源）", () => {
    expect(calls[0].provider).toBe("deepseek");
  });

  it("s2 结算带 interrupted 标记", () => {
    expect(calls[4].interrupted).toBe(true);
  });

  it("归属缺失 → TREND_UNIDENTIFIED 桶", () => {
    expect(calls[4].provider).toBe(TREND_UNIDENTIFIED);
  });

  it("未识别桶 model=null", () => {
    expect(calls[4].model).toBe(null);
  });

  it("零 usage 的 message 结算 token 为 null", () => {
    expect(calls[7].tokens).toBe(null);
  });

  it("#633 目录归属两条线：合法 basename 与缺失归未识别均落盘", () => {
    expect(calls.map((c) => c.dir).sort()).toEqual([
      TREND_UNIDENTIFIED,
      TREND_UNIDENTIFIED,
      TREND_UNIDENTIFIED,
      "proj-a",
      "proj-a",
      "proj-a",
      "proj-a",
      "proj-b",
      "proj-b",
    ]);
  });

  it("身份快照键数 == call 事件数（correct 不新增）", () => {
    expect(finalByKey.size).toBe(calls.length);
  });

  it("回放覆盖两天（跨天逐日对账）", () => {
    expect(days).toEqual([DAY0, DAY1]);
  });
});

describe("台账守恒对账（a→b→c→d 四视角逐日）", () => {
  const views = [
    { label: "a→b：Σ事件 vs 内存桶 buckets 合计", totalsOf: bucketsTotalsOf },
    { label: "a→c：Σ事件 vs rollupSnapshot.aggRows 合计", totalsOf: aggRowsTotalsOf },
    { label: "a→d：Σ事件 vs rollupSnapshot.dirRows 合计", totalsOf: dirRowsTotalsOf },
    { label: "a→d：Σ事件 vs dirRows() 快照（残差应为 0）", totalsOf: dirSnapshotTotalsOf },
  ];

  for (const day of days) {
    for (const v of views) {
      it(`[${day}] ${v.label}`, () => {
        assertEqualTotals(`[${day}] ${v.label}`, expectByDay.get(day)!, v.totalsOf(day));
      });
    }
  }

  // 未识别桶份额逐键对齐（归属/目录缺失不静默丢弃、不双计）
  for (const day of days) {
    const byDir = expectByDayDir.get(day)!;
    for (const [dir, expectedDir] of byDir) {
      it(`[${day}] dir=${dir}（rollupSnapshot 折算）`, () => {
        assertEqualTotals(
          `[${day}] dir=${dir}（rollupSnapshot 折算）`,
          expectedDir,
          dirRowsOfDirTotals(day, dir),
        );
      });

      it(`[${day}] dir=${dir}（dirRows() 快照）`, () => {
        assertEqualTotals(
          `[${day}] dir=${dir}（dirRows() 快照）`,
          expectedDir,
          dirSnapshotOfDirTotals(day, dir),
        );
      });
    }

    it(`[${day}] 该日未识别桶确有份额（防口径空转）`, () => {
      expect(byDir.has(TREND_UNIDENTIFIED)).toBe(true);
    });
  }
});

describe("台账守恒链完整表达式（终态抽查）", () => {
  const day = DAY0;
  const chain = [
    { label: "buckets", totals: () => bucketsTotalsOf(day) },
    { label: "aggRows", totals: () => aggRowsTotalsOf(day) },
    { label: "dirRows", totals: () => dirRowsTotalsOf(day) },
    { label: "dirRows() 快照", totals: () => dirSnapshotTotalsOf(day) },
  ];

  for (const c of chain) {
    it(`[${day}] 守恒链终态（${c.label}）`, () => {
      assertEqualTotals(`[${day}] 守恒链终态`, expectByDay.get(day)!, c.totals());
    });
  }
});

afterAll(() => {
  console.log(
    `unit-trend-ledger: DAY0/DAY1 四视角台账守恒全部通过（calls=${expectByDay.get(DAY0)!.calls + expectByDay.get(DAY1)!.calls}，corrects=${corrects.length}，counters=${counters.length}）`,
  );
});

packages/dsh-provider-usage/test/integra.source:
/**
 * dsh-provider-usage — integration：聚合域组合根四维度（#768 计划表 rev2 D8 验收）。
 *
 * 白盒直连 src（读装配源码文本 + 经 server/aggregate 门面活装配）；落盘一律进
 * mkdtempSync 隔离目录（产物零污染）。四维度：
 * - D8一 经 server/aggregate 域门面装配：TrendTracker/TrendStore/聚合查询纯面只经
 *   server/aggregate/interface.ts，不走旧 domain2/aggregate 入口；apply/apply.ts、
 *   apply/index.ts、server/execute 四文件、server/ui-routes/trend.ts（#768 D12 起，
 *   前为 domain2/routes/ui.ts）的聚合消费收口新门面；
 *   门面禁整文件 re-export；包导出面（apply/index.ts 转发名）收窄后集合（B波）。
 * - D8二 derive/align 聚合查询纯面经门面复用（与 D2 deriveLastRun/alignLastRun 同形）：
 *   查询投影函数显式传参不接触 this；execute 经门面复用 metricValue 纯函数与
 *   TrendTracker 类型，不调业务实例（实例只由组合根构造、经参数传递）。
 * - D8三 deps 注入面窄面：AggregateWarn/AggregateClock/AggregateResolveCwd 命名接缝与
 *   块内联双生子（TrendTrackerOptions 保留内联函数类型，不 import type 本面）；
 *   deps.ts 纯类型面运行时零出口。
 * - D8四 随行修正与冻结：deletePromises 注解文本锁已迁 gate/verify-provider-usage-shape.mjs +
 *   A4(f) 补 dir
 *   （缺键只进 agg 面）+ forgetPersisted 删除（全仓单命中死代码）；
 *   store 多错语义与 resolveCwd/性能预留冻结不动（多错分支行为锁，不改语义）。
 *
 * 每条附判据句（把 X 改坏必须红）；文本哨兵仅锚真实 ABI 与装配关系，不做风格断言。
 */
import { mkdirSync, readFileSync, writeFileSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";
import { afterEach, describe, expect, it } from "vitest";
import { cleanupIsolatedDirs, containsAny, hasExportStar, makeIsolatedDir } from "../../helpers.ts";
import {
  TrendAggregator,
  TrendTracker,
  TrendStore,
  metricValue,
  weekStartKey,
  lastNWeekKeys,
  lastNMonthKeys,
  monthRange,
  weekRange,
  mergeAggRows,
  mergeDirRows,
  mergeHourRows,
} from "../../../src/server/aggregate/interface.ts";
import { TrendAggregator as ImplAggregator } from "../../../src/server/aggregate/aggregator.ts";
import { TrendTracker as ImplTracker } from "../../../src/server/aggregate/index.ts";
import { TrendStore as ImplStore } from "../../../src/server/aggregate/store.ts";
import {
  metricValue as ImplMetricValue,
  weekStartKey as ImplWeekStartKey,
  lastNWeekKeys as ImplLastNWeekKeys,
  lastNMonthKeys as ImplLastNMonthKeys,
  monthRange as ImplMonthRange,
  weekRange as ImplWeekRange,
} from "../../../src/server/aggregate/aggregate-query.ts";
import {
  mergeAggRows as ImplMergeAgg,
  mergeDirRows as ImplMergeDir,
  mergeHourRows as ImplMergeHour,
} from "../../../src/server/aggregate/aggregate-rows.ts";
import * as aggregateDepsNs from "../../../src/server/aggregate/deps.ts";
import type {
  AggregateWarn,
  AggregateClock,
  AggregateResolveCwd,
} from "../../../src/server/aggregate/deps.ts";
import { TREND_ROW_VERSION } from "../../../src/server/shared/interface.ts";
import { TrendCollector } from "../../../src/server/collect/interface.ts";

const here = dirname(fileURLToPath(import.meta.url));
const srcDir = join(here, "..", "..", "..", "src");
const repoRoot = join(here, "..", "..", "..", "..", "..");
const applySrc = readFileSync(join(srcDir, "apply", "apply.ts"), "utf8");
const applyFaceSrc = readFileSync(join(srcDir, "apply", "index.ts"), "utf8");
const runnerSrc = readFileSync(join(srcDir, "server", "execute", "runner.ts"), "utf8");
const generateSrc = readFileSync(join(srcDir, "server", "execute", "generate.ts"), "utf8");
const listDirsSrc = readFileSync(join(srcDir, "server", "execute", "list-dirs.ts"), "utf8");
const executorSrc = readFileSync(join(srcDir, "server", "execute", "executor.ts"), "utf8");
const executeDepsSrc = readFileSync(join(srcDir, "server", "execute", "deps.ts"), "utf8");
const uiRoutesSrc = readFileSync(join(srcDir, "server", "ui-routes", "trend.ts"), "utf8");
const aggregateFaceSrc = readFileSync(join(srcDir, "server", "aggregate", "interface.ts"), "utf8");
const aggregateDepsSrc = readFileSync(join(srcDir, "server", "aggregate", "deps.ts"), "utf8");
const aggregatorSrc = readFileSync(join(srcDir, "server", "aggregate", "aggregator.ts"), "utf8");
const topologySrc = readFileSync(
  join(repoRoot, "scripts", "data", "mutation-topology.json"),
  "utf8",
);

/** 旧门面判据：任一旧 domain2/aggregate 引用残留即红（针脚为域事实，命中循环见 helpers）。 */
function usesOldFace(src: string): boolean {
  return containsAny(src, ["domain2/aggregate"]);
}

/**
 * 命名接缝消费（类型链接由 tsc 编译面校验可赋值性）：窄面在此复用名称。
 * resolveCwd 缺省不接 store（目录恒归未识别桶）；clock 固定推进可复现。
 */
const warnSeam: AggregateWarn = () => undefined;
const clockSeam: AggregateClock = () => 1_700_000_000_000;
const resolveCwdSeam: AggregateResolveCwd = () => undefined;

const tmpDirs: string[] = [];
function isolatedDir(prefix: string): string {
  return makeIsolatedDir(tmpDirs, prefix);
}
afterEach(() => {
  cleanupIsolatedDirs(tmpDirs);
});

describe("D8一 经 server/aggregate 域门面装配", () => {
  it("组合根与消费方只经新门面取聚合（旧入口残留必须红）", () => {
    for (const src of [
      applySrc,
      applyFaceSrc,
      runnerSrc,
      generateSrc,
      listDirsSrc,
      executorSrc,
      executeDepsSrc,
      uiRoutesSrc,
      aggregateFaceSrc,
      aggregateDepsSrc,
    ]) {
      expect(usesOldFace(src)).toBe(false);
    }
    expect(applySrc.includes("server/aggregate/interface")).toBe(true);
    expect(applyFaceSrc.includes("server/aggregate/interface")).toBe(true);
    expect(runnerSrc.includes("../aggregate/interface")).toBe(true);
    // #768 A波5：metricValue 已下沉 shared，generate 不再经 aggregate 门面（经 shared 纯面）
    expect(generateSrc.includes("../aggregate/interface")).toBe(false);
    expect(generateSrc.includes("../shared/interface")).toBe(true);
  });

  it("门面收口：interface 与实现同一引用（包装即红）", () => {
    expect(TrendAggregator).toBe(ImplAggregator);
    expect(TrendTracker).toBe(ImplTracker);
    expect(TrendStore).toBe(ImplStore);
    expect(metricValue).toBe(ImplMetricValue);
    expect(weekStartKey).toBe(ImplWeekStartKey);
    expect(lastNWeekKeys).toBe(ImplLastNWeekKeys);
    expect(lastNMonthKeys).toBe(ImplLastNMonthKeys);
    expect(monthRange).toBe(ImplMonthRange);
    expect(weekRange).toBe(ImplWeekRange);
    expect(mergeAggRows).toBe(ImplMergeAgg);
    expect(mergeDirRows).toBe(ImplMergeDir);
    expect(mergeHourRows).toBe(ImplMergeHour);
  });

  it("门面禁整文件 re-export（加星导出即红）", () => {
    for (const src of [aggregateFaceSrc, aggregateDepsSrc]) {
      const codeLines = src.split(String.fromCharCode(10)).filter((l) => !l.trim().startsWith("*"));
      expect(hasExportStar(codeLines)).toBe(false);
    }
  });

  it("门面值出口恰为 12 项（多一项即公共面膨胀）", async () => {
    const faceNs = await import("../../../src/server/aggregate/interface.ts");
    expect(Object.keys(faceNs).sort()).toEqual(
      [
        "TrendAggregator",
        "TrendTracker",
        "TrendStore",
        "metricValue",
        "weekStartKey",
        "lastNWeekKeys",
        "lastNMonthKeys",
        "monthRange",
        "weekRange",
        "mergeAggRows",
        "mergeDirRows",
        "mergeHourRows",
      ].sort(),
    );
  });

  it("变异面登记随域改址（旧路径残留即红）", () => {
    for (const p of [
      "src/domain2/aggregate/aggregator.ts",
      "src/domain2/aggregate/aggregate-rows.ts",
      "src/domain2/aggregate/aggregate-query.ts",
      "src/domain2/aggregate/store.ts",
      "src/domain2/aggregate/index.ts",
    ]) {
      expect(topologySrc.includes(p)).toBe(false);
    }
    for (const p of [
      "src/server/aggregate/aggregator.ts",
      "src/server/aggregate/aggregate-rows.ts",
      "src/server/aggregate/aggregate-query.ts",
      "src/server/aggregate/store.ts",
      "src/server/aggregate/index.ts",
    ]) {
      expect(topologySrc.includes(p)).toBe(true);
    }
  });
});

describe("D8二 derive/align 聚合查询纯面经门面复用", () => {
  it("metricValue 纯面活可用（total = 四项 token 之和；删调用即红）", () => {
    expect(
      metricValue(
        {
          input: 1,
          output: 2,
          cacheRead: 3,
          cacheWrite: 4,
          calls: 9,
          turns: 0,
          toolCalls: 0,
        },
        "total",
      ),
    ).toBe(10);
    expect(
      metricValue(
        {
          input: null,
          output: 5,
          cacheRead: null,
          cacheWrite: null,
          calls: 1,
          turns: 0,
          toolCalls: 0,
        },
        "total",
      ),
    ).toBe(5);
  });

  it("mergeDirRows 同键累加经门面可达（迟到旧日行二次压实防丢防重）", () => {
    const day = "2026-09-04";
    const base = [
      {
        v: TREND_ROW_VERSION,
        kind: "dir" as const,
        day,
        dir: "x",
        input: 1,
        output: 1,
        cacheRead: null,
        cacheWrite: null,
        calls: 1,
        turns: 0,
        toolCalls: 0,
      },
    ];
    const merged = mergeDirRows(base, base);
    expect(merged).toHaveLength(1);
    expect(merged[0].input).toBe(2);
    expect(merged[0].calls).toBe(2);
  });
});

describe("D8三 deps 注入面窄面", () => {
  it("deps.ts 纯类型面：运行时零出口", () => {
    expect(Object.keys(aggregateDepsNs)).toEqual([]);
  });

  it("工厂漏传抛错（运行时锁，空实现即红）", async () => {
    const dir = isolatedDir("dou-aggD8-guard-");
    await expect(
      TrendTracker.start({ root: dir } as unknown as Parameters<typeof TrendTracker.start>[0]),
    ).rejects.toThrow("缺少 makeCollector");
  });

  it("命名接缝装配 TrendTracker（改名断链即红；落盘走隔离目录）", async () => {
    const dir = isolatedDir("dou-aggD8-");
    const tracker = await TrendTracker.start({
      makeCollector: (o) => new TrendCollector(o),
      root: dir,
      now: clockSeam,
      flushDebounceMs: 60000,
      warn: warnSeam,
      resolveCwd: resolveCwdSeam,
    });
    expect(tracker.stats()).toEqual({
      days: 0,
      pendingRows: 0,
      unpersistedRows: 0,
      lastFlushAt: null,
    });
    await tracker.dispose();
  });
});

describe("D8四 随行修正与冻结", () => {
  it("tmp 残留清理成功分支：残留删、主写成（删清理即红）", async () => {
    const dir = isolatedDir("dou-aggD8-tmp-");
    const day = "2026-09-04";
    const store = new TrendStore({ root: dir });
    mkdirSync(join(dir, "agg"), { recursive: true });
    writeFileSync(join(dir, "agg", `${day}.jsonl.123.tmp`), "stale\n");
    const warns: string[] = [];
    const store2 = new TrendStore({ root: dir, warn: (m) => warns.push(m) });
    await store2.writeAggDay(day, [
      {
        v: TREND_ROW_VERSION,
        kind: "agg" as const,
        day,
        provider: "pv",
        model: null,
        input: 1,
        output: 2,
        cacheRead: null,
        cacheWrite: null,
        calls: 1,
        turns: 0,
        toolCalls: 0,
      },
    ]);
    expect(warns).toEqual([]);
    expect(await store.readAggDayShard(day)).toHaveLength(1);
  });

  it("store 多错语义冻结：清理失败仅 warn、主写照常推进（吞错/抛错即红）", async () => {
    const dir = isolatedDir("dou-aggD8-multi-");
    const day = "2026-09-04";
    // 非空目录冒充 tmp 残留：无 recursive 的 rm 必拒（清理失败分支可复现）。
    const badTmp = join(dir, "agg", `${day}.jsonl.456.tmp`);
    mkdirSync(badTmp, { recursive: true });
    writeFileSync(join(badTmp, "inner.txt"), "x");
    const warns: string[] = [];
    const store = new TrendStore({ root: dir, warn: (m) => warns.push(m) });
    await store.writeAggDay(day, [
      {
        v: TREND_ROW_VERSION,
        kind: "agg" as const,
        day,
        provider: "pv",
        model: null,
        input: 7,
        output: 8,
        cacheRead: null,
        cacheWrite: null,
        calls: 2,
        turns: 1,
        toolCalls: 1,
      },
    ]);
    expect(warns).toHaveLength(1);
    expect(warns[0]).toContain("tmp");
    const rows = await store.readAggDayShard(day);
    expect(rows).toHaveLength(1);
    expect(rows[0].calls).toBe(2);
  });

  it("forgetPersisted 已删除（定义残留/原型残留即红）", () => {
    expect(aggregatorSrc.includes("forgetPersisted")).toBe(false);
    expect("forgetPersisted" in TrendAggregator.prototype).toBe(false);
  });
});

describe("探针：detector 失明则本段先红", () => {
  it("旧门面 detector 对脏输入有效", () => {
    expect(usesOldFace("import { x } from ../domain2/aggregate/interface.ts")).toBe(true);
    expect(usesOldFace("import { x } from ../server/aggregate/interface.ts")).toBe(false);
  });

  it("export * detector 对脏输入有效", () => {
    expect(hasExportStar(["export * from ./store.ts"])).toBe(true);
    expect(hasExportStar(["export { a } from ./store.ts"])).toBe(false);
  });
});

